import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system = platform.system()
    data = []
    start_time = time.time()
    while True:
        current_time = time.time()
        if current_time - start_time > duration:
            break
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(current_time))
        cpu_usage = None
        try:
            if system == "Windows":
                process = subprocess.Popen(["wmic", "cpu", "get", "loadpercentage", "/value"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                stdout, stderr = process.communicate()
                output = stdout.decode(errors="ignore")
                for line in output.splitlines():
                    if "LoadPercentage" in line:
                        parts = line.split("=")
                        if len(parts) == 2:
                            try:
                                cpu_usage = float(parts[1].strip())
                            except ValueError:
                                cpu_usage = None
                        break
            else:
                process = subprocess.Popen(["top", "-bn1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                stdout, stderr = process.communicate()
                output = stdout.decode(errors="ignore")
                for line in output.splitlines():
                    line_lower = line.lower()
                    if "cpu(s)" in line_lower or "%cpu" in line_lower:
                        parts = line.replace(",", ".").split()
                        for i, part in enumerate(parts):
                            if "id" in part.lower():
                                try:
                                    idle_str = parts[i - 1]
                                    idle = float(idle_str)
                                    cpu_usage = 100.0 - idle
                                except Exception:
                                    cpu_usage = None
                                break
                        if cpu_usage is None:
                            for i, part in enumerate(parts):
                                if part.lower().startswith("us") or part.lower().startswith("user"):
                                    try:
                                        cpu_usage = float(parts[i - 1])
                                    except Exception:
                                        cpu_usage = None
                                    break
                        break
        except Exception:
            cpu_usage = None
        record = {"timestamp": timestamp, "cpu_usage": cpu_usage}
        data.append(record)
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

import subprocess
import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError("Commands file does not exist")
    if not os.path.isdir(output_dir_path):
        os.makedirs(output_dir_path, exist_ok=True)
    output_files = []
    with open(commands_file_path, newline='') as csvfile:
        reader = csv.reader(csvfile)
        for index, row in enumerate(reader):
            if not row:
                command = ""
            else:
                command = row[0]
            output_file_path = os.path.join(output_dir_path, f"command_{index}_output.txt")
            try:
                result = subprocess.run(command, shell=True, capture_output=True, text=True)
                with open(output_file_path, "w", encoding="utf-8") as f:
                    if result.stdout:
                        f.write(result.stdout)
                    if result.returncode != 0:
                        if result.stderr:
                            f.write(result.stderr)
                        f.write(f"\nExit code: {result.returncode}")
            except Exception as e:
                with open(output_file_path, "w", encoding="utf-8") as f:
                    f.write(f"Failed to execute command: {e}")
            output_files.append(output_file_path)
    return output_files

