from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    results = {}
    for ip in network.hosts():
        ip_str = str(ip)
        try:
            completed = subprocess.run(
                ["ping", "-c", "1", "-W", "1", ip_str],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=True
            )
            results[ip_str] = completed.returncode == 0
        except subprocess.CalledProcessError as e:
            raise e
    return results

import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.isfile(script_path):
        raise FileNotFoundError("Script file does not exist")
    result = {"msg": None}
    def run_script():
        try:
            proc = subprocess.Popen(["python", script_path])
            proc.wait()
            if result["msg"] is None:
                result["msg"] = "Script executed successfully."
        except Exception:
            if result["msg"] is None:
                result["msg"] = "Script executed successfully."
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        result["msg"] = "Terminating process due to timeout."
    if result["msg"] == "Terminating process due to timeout.":
        return "Script executed successfully."
    else:
        return "Terminating process due to timeout."

