def task_func(test_dir):
    results = {}
    if not isinstance(test_dir, str):
        return results
    test_dir = os.path.abspath(test_dir)
    pattern = os.path.join(test_dir, "*.py")
    scripts = glob.glob(pattern)
    for script in scripts:
        if not os.path.isfile(script):
            continue
        start = time.time()
        try:
            subprocess.run(["python", script], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except Exception:
            pass
        end = time.time()
        results[os.path.basename(script)] = end - start
    return results

