        raise ValueError("Script does not exist")
    cmd = [sys.executable, script_path]
    for arg in args:
        cmd.append(str(arg))
    if wait:
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
