from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': []}
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception:
            return {'success': False, 'message': 'Failed to create destination folder', 'failed_files': []}
    pattern = os.path.join(src_folder, '*')
    files = [f for f in glob(pattern) if os.path.isfile(f)]
    for file_path in files:
        try:
            proc = subprocess.Popen(['gzip', '-f', file_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            failed_files.append(os.path.basename(file_path))
            continue
        proc.wait()
        if proc.returncode != 0:
            failed_files.append(os.path.basename(file_path))
            continue
        gz_path = file_path + '.gz'
        if not os.path.exists(gz_path):
            failed_files.append(os.path.basename(file_path))
            continue
        try:
            shutil.move(gz_path, os.path.join(dst_folder, os.path.basename(gz_path)))
        except Exception:
            failed_files.append(os.path.basename(file_path))
    if failed_files:
        return {'success': False, 'message': 'Some files failed to compress or move', 'failed_files': failed_files}
    return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}

