import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not isinstance(pattern, str):
        raise TypeError("Invalid pattern type")
    if not os.path.exists(ARCHIVE_DIR):
        os.makedirs(ARCHIVE_DIR, exist_ok=True)
    matched_files = glob.glob(pattern)
    matched_files = [f for f in matched_files if os.path.isfile(f)]
    if not matched_files:
        raise FileNotFoundError("No files matched the given pattern")
    base_name = os.path.basename(pattern.replace(os.sep, "_").replace("*", "star").replace("?", "qmark"))
    if not base_name:
        base_name = "archive"
    archive_path = os.path.join(ARCHIVE_DIR, base_name + ".tar.gz")
    cmd = ["tar", "-czf", archive_path] + matched_files
    try:
        subprocess.check_call(cmd)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Failed to create archive") from e
    for f in matched_files:
        try:
            os.remove(f)
        except OSError:
            pass
    return archive_path

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path) or not os.path.isfile(script_path):
        raise OSError("Script path does not exist or is not a file")
    start_time = time.time()
    process = subprocess.Popen(["bash", script_path])
    ps_proc = psutil.Process(process.pid)
    cpu_accum = 0.0
    mem_accum = 0
    last_cpu_times = None
    interval = 0.1
    try:
        while True:
            if time.time() - start_time > timeout:
                process.terminate()
                try:
                    process.wait(timeout=5)
                except Exception:
                    process.kill()
                break
            try:
                if ps_proc.status() == psutil.STATUS_ZOMBIE:
                    break
            except psutil.NoSuchProcess:
                break
            try:
                cpu_times = ps_proc.cpu_times()
                if last_cpu_times is not None:
                    delta_user = cpu_times.user - last_cpu_times.user
                    delta_system = cpu_times.system - last_cpu_times.system
                    delta_cpu = max(delta_user + delta_system, 0.0)
                    cpu_accum += delta_cpu * 100.0
                last_cpu_times = cpu_times
            except psutil.NoSuchProcess:
                break
            try:
                mem_info = ps_proc.memory_info()
                mem_accum += max(mem_info.rss, 0)
            except psutil.NoSuchProcess:
                break
            if process.poll() is not None:
                break
            time.sleep(interval)
    finally:
        if process.poll() is None:
            try:
                process.terminate()
                process.wait(timeout=5)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass
    return {"CPU Usage": cpu_accum, "Memory Usage": mem_accum}

